```c
#include <stdio.h>
#include <string.h>

void print_label(const char *text) {      /* BORROWER: uses text during the call. */
    printf("[%s]\n", text);
}

int main(void) {
    const char *saved = NULL;
    if (1) {
        char buf[16];                     /* automatic: lives until this } ends. */
        strcpy(buf, "hello");
        print_label(buf);                 /* fine: buf is alive. */
        saved = buf;                      /* copy of the address... */
    }                                     /* buf's lifetime ends HERE. */
    /* printf("%s", saved);  undefined: saved is dangling. */

    static char keep[16] = "kept";       /* static: lives for the whole program. */
    saved = keep;
    print_label(saved);                   /* fine. */
    return 0;
}
```

| Storage | Lifetime ends | Owner releases by |
|---|---|---|
| automatic. | end of its block. | leaving the block (automatic). |
| static. | program end. | nothing needed. |
| allocated. | `free`. | calling free exactly once. |

